// Nettoie un DOI et le rend utilisable dans une adresse. Rend une chaine vide si le DOI est
// inexploitable : l'appelant la retire du lot, et les autres partent normalement.
function _doiPourUrl(d) {
  if (!d) return '';
  var s = String(d).replace(/[�-]/g, '').trim();
  if (!s) return '';
  return encodeURIComponent(s);
}
// Nettoie un DOI sans l'encoder : pour un corps de requete, pas pour une adresse.
function _doiNet(d) {
  return String(d || '').replace(/[\u0000-\u001F\u007F]/g, '').trim();
