// SNOWBALLING_v2 (v0.2.9) - chainage de citations multi-sources
// Sources : OpenAlex (cited_by/cites), Semantic Scholar (references/citations),
// Europe PMC (references/citations), OpenCitations COCI (references/citations, enrichi via OpenAlex).
// Backward = references ; Forward = citations. Dedup vs corpus + entre sources (provenance _snowball_sources).
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const seeds = items.map(i => i.json);
const seed0 = seeds[0] || {};

let DIRECTIONS = 'both';
let FWD_CAP = 100;
let __cleOA = false;
let SOURCES = ['openalex','semanticscholar','europepmc','opencitations'];
try {
  const cfg = await this.helpers.httpRequest({ method:'GET', url:'http://host.docker.internal:8080/api/config', timeout:5000, json:true }) || {};
  if (cfg.snowball_directions === 'backward' || cfg.snowball_directions === 'forward' || cfg.snowball_directions === 'both') DIRECTIONS = cfg.snowball_directions;
  if (typeof cfg.snowball_forward_cap === 'number' && cfg.snowball_forward_cap > 0) FWD_CAP = Math.min(cfg.snowball_forward_cap, 200);
  if (Array.isArray(cfg.snowball_sources) && cfg.snowball_sources.length) SOURCES = cfg.snowball_sources;
  // Presence de la cle de la base bibliographique ouverte (2026-10-19) : voir __pagesOA, plus bas.
  __cleOA = !!(cfg.secrets_definis && cfg.secrets_definis.openalex_api_key === true);
} catch(e) {}
if (Array.isArray(seed0._snowball_sources_override) && seed0._snowball_sources_override.length) SOURCES = seed0._snowball_sources_override;
const SRC = {}; SOURCES.forEach(function(s){ SRC[s]=true; });
// LE CHOIX DE L'UTILISATEUR EST HONORE (2026-08-18).
//
// Cette ligne posait `SRC.openalex = true` sans condition, au motif que cette base sert aussi
// a resoudre les DOI et a enrichir les resultats d'OpenCitations. C'etait defendable, mais
// l'interface propose de la desactiver : une case qui ne fait rien est pire qu'une case
// absente. L'utilisateur l'a decoche et la base a continue d'etre appelee.
//
// On respecte donc le reglage. Ce que cela coute est ECRIT dans le resume du run, pour que
// la perte se lise au lieu de se deviner : sans cette base, les DOI se resolvent moins bien
// et les references venues d'OpenCitations restent moins renseignees.
const __oaDemande = SRC.openalex === true;

const OA_SELECT = 'id,doi,display_name,publication_year,authorships,primary_location,cited_by_count,abstract_inverted_index';
const doBack = (DIRECTIONS === 'both' || DIRECTIONS === 'backward');
const doFwd  = (DIRECTIONS === 'both' || DIRECTIONS === 'forward');
// PAGES DE 100 PAR CURSEUR, QUAND UNE CLE EST ENREGISTREE (2026-10-19, lot 0 de la 0.5.3). La base
// bibliographique ouverte fixe sa taille de page a 100 ; 200, la taille des deux listes de chaque
// graine plus bas, n'y est plus que toleree (page de pagination de la base, mise a jour le
// 2026-10-14, lue par le dossier de preparation de la 0.5.4). Or paginer au-dela de la premiere page
// exige une cle : sans cle, la page 2 par curseur rend 401 (mesure publique du 2026-10-19).
//   - AVEC CLE (posee par le relais, proxy._ENTETES_PAR_HOTE ; ce noeud n'en lit que la presence,
//     `secrets_definis` de /api/config) : pages de 100 par curseur, jusqu'au meme plafond qu'avant
//     (200 references, ou le plafond aval regle) ;
//   - SANS CLE : la demande d'avant, A L'IDENTIQUE (une page unique, de 200 au plus). Passer a 100
//     sans pouvoir paginer perdrait les references 101 a 200 d'une graine qui en a davantage, que la
//     taille toleree rend encore. DECISION PRUDENTE, SIGNALEE : a revoir si la base retire cette
//     tolerance ; ses refus se compteraient alors par base (`appels_refuses` du resume).
// Garde : tests/test_cle_openalex_chainage.py.
const OA_PAR_PAGE = 100;
async function __pagesOA(adresse, plafond) {
  const premiere = await get(adresse + '&per_page=' + Math.min(plafond, OA_PAR_PAGE) + '&cursor=*');
  if (!premiere || !premiere.results) return premiere;
  let rendus = premiere.results.slice(0, plafond);
  let curseur = premiere.meta && premiere.meta.next_cursor;
  while (curseur && rendus.length < plafond) {
    const suite = await get(adresse + '&per_page=' + OA_PAR_PAGE + '&cursor=' + encodeURIComponent(curseur));
    if (!suite || !suite.results || !suite.results.length) break;
    rendus = rendus.concat(suite.results).slice(0, plafond);
    curseur = suite.meta && suite.meta.next_cursor;
  }
  return { results: rendus };
}

function norm(t){ return (t||'').toString().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(); }
// LE TITRE APLATI : tout separateur SUPPRIME, et non remplace par une espace. C'est la
// regle du noeud de deduplication, et les deux noeuds du meme moteur repondaient jusqu'ici
// differemment a « est-ce le meme article ? ». Mesure sur le run reel de 101 044 candidats
// contre 5 660 graines : 23 classes differemment, tous dans le sens « le chainage dit
// nouveau, la deduplication dit deja connu ». Vingt et un sont la MEME oeuvre, ramenee sans
// DOI avec l'espacement casse par la mise en page d'origine (« Briefimageryrescriptingvs.
// usualcare », « tra ffi cked », « post-traumatic » contre « posttraumatic »).
function aplat(t){ return (t||'').toString().toLowerCase().replace(/[^a-z0-9]/g,''); }
// PLANCHER DE LONGUEUR, ET IL VIENT D'UNE MESURE, PAS D'UNE INTUITION. Le noeud de
// deduplication l'impose deja pour sa strategie « titre seul » (durcissement A7). Sans lui,
// « P.T.S.D. » et « PTSD » fusionnent, comme « COVID-19 » et « COVID19 » : le corpus de
// graines de l'auteur porte 93 clefs aplaties de moins de 20 caracteres, dont « 404 »,
// « 2329 », « assessment », « comorbidity ». Les 23 vrais rapprochements font tous 20
// caracteres ou plus : le plancher ne coute rien et evite trois faux positifs mesures.
const PLAT_MIN = 20;
function cleanDoi(d){
  // LA REGLE CANONIQUE, MOT POUR MOT : `src/text_norm.norm_doi` et `parse.ts`.
  // TROIS RETRAITS BORNES, PAS UNE BOUCLE : le texte, puis l'adresse, puis le texte a
  // nouveau. Les deux ordres composes existent (`doi:https://doi.org/x` et
  // `https://doi.org/doi:x`) et un ordre fixe en laissait toujours un passer. Le rognage
  // vient EN PREMIER : sans lui, un espace de tete empeche le retrait de l'adresse.
  // COUT MESURE DE CET ALIGNEMENT AUJOURD'HUI : ZERO. Sur les 376 042 identifiants reels
  // des fichiers du poste, l'ancienne regle et celle-ci rendent la MEME valeur, et aucune
  // notice ne porte le prefixe textuel. C'est de la robustesse : le lecteur Python vient
  // d'etre aligne, les noeuds etaient la derniere moitie en retard, et deux regles pour
  // une seule notion divergent le jour ou l'une est corrigee.
  return String(d || '').trim().toLowerCase()
    .replace(/^doi\s*:\s*/, '')
    .replace(/^https?:\/\/(dx\.)?doi\.org\//, '')
    .replace(/^doi\s*:\s*/, '')
    .trim();
}
// RESUME ENTIER, ICI AUSSI (2026-09-11). Cette reconstruction coupait a 2 000 caracteres : un
// resume OpenAlex de 3 501 ressortait ampute, quand le meme candidat venu de Semantic Scholar
// arrivait entier et que le noeud de normalisation reconstruit le meme index sans coupe. Elle
// sert deux fois : les candidats OpenAlex (mapOA) et l'enrichissement des resumes manquants.
// La borne ne protegeait aucune taille en aval (mesure du 2026-09-11) : le tri calcule son
// contexte sur le plus long prompt du run et signale une coupe, les plongements, le classement
// et le regroupement portent chacun leur borne, et le journal de reprise n'en a aucune.
// tests/test_resume_reconstruit_entier.py execute le noeud sur les deux chemins.
function recon(inv){ if(!inv) return ''; const w=[]; for(const k in inv){ const ps=inv[k]; for(let i=0;i<ps.length;i++){ w[ps[i]]=k; } } return w.join(' ').replace(/\s+/g,' ').trim(); }
// QUOTA EPUISE : ON LE CONSTATE UNE FOIS, POUR CHAQUE BASE (2026-08-18).
//
// MESURE FONDATRICE, run reel de 5 668 references. La base historique repondait 429 a 685
// appels sur 692 : « Insufficient budget. This request costs $0.0001 but you only have $0
// remaining. Resets at midnight UTC », Retry-After 46517, quota restant 0. Le budget du jour
// etait epuise, AUCUN appel ne pouvait aboutir avant minuit. Or le nœud reessayait chaque
// adresse trois fois avec 1,5 s puis 3 s d'attente : 4,5 s brulees par adresse pour un refus
// connu d'avance, sur 230 adresses dans la seule fenetre observee.
//
// LE CONSTAT VAUT POUR TOUTE BASE, pas seulement celle qui a montre le defaut : concentrer la
// charge sur une autre reproduirait la meme impasse ailleurs. On retient donc l'epuisement par
// base, et le run continue avec les autres au lieu de s'enliser.
const __epuise = {};        // base -> motif, quand elle a declare forfait pour la journee
const __evites = {};        // base -> appels evites grace a ce constat

// CADENCE PAR BASE, en millisecondes entre deux DEBUTS d'appel.
//
// MESURE DU 2026-08-18 sur la base de citations principale, adresses toutes differentes, rythme
// tenu quatre-vingt-dix secondes d'affilee, une minute de recuperation entre deux rythmes :
//   1 appel / 1,45 s ->  0 refus sur  62
//   1 appel / 0,91 s ->  0 refus sur  99
//   1 appel / 0,59 s -> 48 refus sur 152, le premier des le 49e appel, 92 % sur le dernier tiers
//
// POURQUOI LA MESURE A DU ETRE REFAITE DEUX FOIS. Un premier banc de douze appels par palier ne
// montrait AUCUN refus, meme sans le moindre espacement : douze appels n'atteignent pas le seuil,
// c'est le volume SOUTENU qui le declenche. Mesurer trop court aurait fait conclure « aucun
// espacement necessaire », et le run se serait enlise de nouveau. Le banc d'avant celui-la avait
// l'erreur inverse : lance juste apres un run, il mesurait la punition laissee par ce run et
// refusait meme a 1 600 ms. D'ou la recuperation entre paliers.
//
// CE QUE CELA CORRIGE. Pendant un run reel, 236 appels sur 311 etaient refuses et chaque adresse
// etait demandee 3,1 fois. Un appel qui aboutit repond en 0,50 s ; ce sont les reessais, avec
// leurs 1,5 s puis 3 s d'attente, qui coutaient les secondes. Ralentir chaque appel accelere donc
// le run, au lieu de le ralentir.
const __CADENCE_MS = { semanticscholar: 1000, openalex: 120 };
const __dernierDepart = {};

async function __attendreSonTour(base) {
  const mini = __CADENCE_MS[base] || 0;
  if (!mini) return;
  const attente = (__dernierDepart[base] || 0) + mini - Date.now();
  if (attente > 0) await new Promise(function (r) { setTimeout(r, attente); });
  // Le repere se pose au DEPART de l'appel, jamais a son arrivee. Pose a l'arrivee, la duree de
  // l'appel s'ajoute a l'espacement voulu : 120 ms d'espacement devenaient 620 ms de periode
  // reelle, soit cinq fois moins d'appels que ce que le reglage annonce.
  __dernierDepart[base] = Date.now();
}

function __baseDe(u) {
  const s = String(u || '');
  if (s.indexOf('api.openalex.org') >= 0) return 'openalex';
  if (s.indexOf('api.semanticscholar.org') >= 0) return 'semanticscholar';
  if (s.indexOf('api.crossref.org') >= 0) return 'crossref';
  if (s.indexOf('ebi.ac.uk') >= 0) return 'europepmc';
  if (s.indexOf('opencitations.net') >= 0) return 'opencitations';
  return 'autre';
}

function __codeDe(e) {
  return (e && (e.statusCode || (e.response && e.response.statusCode))) || 0;
}

function __annonceEpuisement(e) {
  // Vrai quand le refus porte sur le BUDGET du jour, pas sur une rafale passagere. Une rafale
  // se traite par le reessai ; fermer la base pour autant la priverait de tout le run.
  const h = (e && e.response && e.response.headers) || {};
  const reste = h['x-ratelimit-remaining'] !== undefined ? String(h['x-ratelimit-remaining']) : null;
  const apres = parseInt(h['retry-after'] || (e && e.response && e.response.body
                && e.response.body.retryAfter) || 0, 10) || 0;
  let corps = '';
  try { corps = JSON.stringify((e && e.response && e.response.body) || '').slice(0, 300); } catch (x) {}
  if (reste === '0') return 'budget du jour epuise (quota restant : 0)';
  if (apres >= 600) return 'reprise annoncee dans ' + Math.round(apres / 60) + ' minutes';
  if (/insufficient budget|rate limit exceeded/i.test(corps)) return 'budget du jour epuise';
  return null;
}

function __horsService(base, motif) {
  __epuise[base] = motif;
  console.log('Base ' + base + ' hors service pour ce run : ' + motif
              + '. Les appels suivants sont evites.');
}

async function __appeler(url, corps) {
  const base = __baseDe(url);
  if (__epuise[base]) { __evites[base] = (__evites[base] || 0) + 1; return null; }
  let u = url;
  if (base === 'openalex') {
    u += (u.indexOf('?') >= 0 ? '&' : '?') + 'mailto=ultralab-review@systematic-review.org';
  }
  let attempt = 0;
  while (true) {
    await __attendreSonTour(base);
    try {
      // LE MODE DE L'APPELANT (2026-10-19) : le relais decide le refus d'un arret sur ce
      // mode, et non plus sur le dernier avancement ouvert (src/proxy.py, `_arret_demande`).
      const opt = { url: PROXY + '?url=' + encodeURIComponent(u) + '&_ultralab_module=snowballing', json: true, timeout: 40000 };
      if (corps === undefined) {
        opt.method = 'GET';
      } else {
        opt.method = 'POST';
        opt.body = corps;
        opt.headers = { 'Content-Type': 'application/json' };
      }
      const __r = await this.helpers.httpRequest(opt);
      __compter(__ok, base);
      return __r;
    } catch (e) {
      attempt++;
      __compter(__refus, base);
      const code = __codeDe(e);
      if (code === 429) {
        const motif = __annonceEpuisement(e);
        if (motif) {
          __horsService(base, motif);
          __compter(__perdus, base);
          return null;
        }
      }
      if (attempt >= 3) { __compter(__perdus, base); return null; }
      const delay = (code === 429 ? 1500 : 600) * attempt;
      await new Promise(function (r) { setTimeout(r, delay); });
    }
  }
}

const get = async (url) => __appeler.call(this, url);
const post = async (url, corps) => __appeler.call(this, url, corps);

// LE PLAFOND DOIT GARDER LES PLUS CITES, PAS LES PREMIERS ARRIVES.
//
// Seule la base historique triait ses citants par nombre de citations ; les autres rendaient
// leur ordre interne, et couper dedans revenait a prendre un echantillon arbitraire. Ce n'est
// pas defendable dans une revue systematique.
//
// Or le compte de citations est DEJA rendu par les deux autres bases (`citationCount` et
// `citedByCount`) et deja recopie dans chaque candidat : il suffisait de s'en servir. On
// recupere donc large, on trie, puis on coupe.
//
// CE QUE CELA NE FAIT PAS : classer parmi TOUS les citants. On classe parmi ceux qu'on a
// recuperes. Recuperer quatre fois le plafond donne une marge raisonnable sans multiplier les
// appels ; au-dela de mille, les bases refusent.
const LARGEUR_TRI = Math.min(1000, Math.max(FWD_CAP * 4, 200));

function __plusCites(cands, cap) {
  const propres = (cands || []).filter(Boolean);
  propres.sort(function (a, b) { return (b.cited_by_count || 0) - (a.cited_by_count || 0); });
  return propres.slice(0, cap);
}

function mapCrossref(w) {
  if (!w) return null;
  const auteurs = (w.author || []).map(function (a) {
    return [a.given, a.family].filter(Boolean).join(' ');
  }).filter(Boolean);
  const dp = (w.issued && w.issued['date-parts'] && w.issued['date-parts'][0]) || [];
  return { title: (w.title || [])[0] || '', doi: cleanDoi(w.DOI || ''),
           year: dp[0] ? String(dp[0]) : '', authors: auteurs,
           journal: (w['container-title'] || [])[0] || '', abstract: '',
           cited_by_count: w['is-referenced-by-count'] || 0 };
}

function mapOA(w){ if(!w) return null; const authors=(w.authorships||[]).map(a=>a.author && a.author.display_name).filter(Boolean); const journal=(w.primary_location && w.primary_location.source && w.primary_location.source.display_name)||''; return { title:w.display_name||'', doi:cleanDoi(w.doi), year:w.publication_year?String(w.publication_year):'', authors:authors, journal:journal, abstract:recon(w.abstract_inverted_index), cited_by_count:w.cited_by_count||0, openalex_id:w.id||'' }; }
function mapS2(p){ if(!p) return null; const ex=p.externalIds||{}; return { title:p.title||'', doi:cleanDoi(ex.DOI||''), year:p.year?String(p.year):'', authors:(p.authors||[]).map(function(a){return a.name;}).filter(Boolean), journal:p.venue||'', abstract:p.abstract||'', cited_by_count:p.citationCount||0 }; }
function mapEPMC(it){ if(!it) return null; return { title:it.title||'', doi:cleanDoi(it.doi||''), year:it.pubYear?String(it.pubYear):'', authors:(it.authorString||'').split(/,\s*/).filter(Boolean), journal:it.journalAbbreviation||'', abstract:'', cited_by_count:it.citedByCount||0 }; }

const corpusDoi = new Set(), corpusTitle = new Set();
// CE QUI EST COMPTE ICI, CE SONT DES REFERENCES, PAS DES APPARIEMENTS. La meme reference
// ecartee sous trente graines comptait trente fois, alors que la statistique voisine
// (candidates_unique) compte des references DISTINCTES : les deux etaient affichees cote a
// cote et ne s'additionnaient pas. Mesure sur le run reel de l'auteur : 33 342 annonces pour
// un corpus de 5 668 graines dont les clefs atteignables plafonnent a 10 897, donc au moins
// 3,1 fois trop. Preuve par execution du noeud : trois graines citant la MEME reference
// rendaient 3 pour une seule reference ecartee.
// La clef est celle que `__noterAjout` emploie deja dans ce meme noeud : deux clefs pour une
// seule notion divergeraient.
const ecartesVus = new Set();
const vusParSource = {};
const corpusPlat = new Map();
for (const s of seeds){ const d=cleanDoi(s.doi); if(d) corpusDoi.add(d); const t=norm(s.title); if(t) corpusTitle.add(t);
  // UN ENSEMBLE DE DOI PAR CLEF, ET NON UN SEUL. Deux graines peuvent partager une clef
  // aplatie, l'une avec DOI et l'autre sans : n'en garder qu'un laissait la derniere posee
  // ecraser la premiere, le veto devenait inerte, et un candidat au DOI etranger etait
  // fusionne. Deux occurrences reelles dans le corpus de graines de l'auteur.
  const p = aplat(s.title);
  if (p.length >= PLAT_MIN) { if (!corpusPlat.has(p)) corpusPlat.set(p, new Set());
    if (d) corpusPlat.get(p).add(d); }
}

const summary = { seeds: seeds.length, seeds_resolved: 0, by_source: {}, candidates_unique: 0, removed_in_corpus: 0, removed_in_corpus_appariements: 0, directions: DIRECTIONS, forward_cap: FWD_CAP, sources: SOURCES.slice() , openalex_demande: __oaDemande };
// Renseigne en fin de parcours : une source epuisee ou ecartee change ce que le run
// pouvait trouver, et cela doit se lire dans le resume, pas seulement dans un journal.
summary.source_epuisee = null; summary.appels_evites = 0;
SOURCES.forEach(function(s){ summary.by_source[s]={backward:0,forward:0}; });
const store = {}; const doiIndex = {}; const titleIndex = {}; let _cid = 0;

// CE QUE LE RUN N'A PAS OBTENU DOIT SE LIRE DANS LE RESUME (2026-08-18).
//
// MESURE QUI L'IMPOSE. Sur un run de 4 361 graines : 16 761 appels a la base de citations,
// 13 055 refuses, 3 708 aboutis. Soit 0,85 reponse par graine la ou il en faut deux, et 55 %
// des graines n'ont RIEN obtenu de cette base. Le nœud passait a la suivante en silence, et le
// dossier produit ne portait aucune trace de ce trou.
//
// Un chainage amoindri n'est pas un chainage lent : c'est une etape de methode qu'on ne peut
// plus declarer telle quelle dans une revue. Le run doit donc annoncer sa propre incompletude.
const __ok = {};        // base -> appels aboutis
const __refus = {};     // base -> refus recus, toutes tentatives confondues
const __perdus = {};    // base -> appels ABANDONNES apres tous les reessais (donnee jamais eue)
const __vides = {};     // base -> graines pour lesquelles cette base n'a rien rendu du tout
const __completes = {}; // base -> graines pour lesquelles elle a rendu tous les sens demandes
function __compter(t, base) { t[base] = (t[base] || 0) + 1; }

// LE TAMPON DU JOURNAL. On enregistre l'AJOUT tel qu'il s'est produit (la notice, son sens, sa
// graine, sa source), pas l'etat fusionne : rejouer ces ajouts dans l'ordre reconstruit
// exactement le meme ensemble. Enregistrer l'etat fusionne obligerait a refaire la fusion a
// l'envers, et une fusion inversee approximative vaudrait moins que pas de reprise du tout.
//
// UNE NOTICE N'EST ECRITE QU'A SA PREMIERE APPARITION. Les fois suivantes, seule sa clef part
// (quelques dizaines d'octets au lieu de plusieurs centaines) : la meme reference revient sous
// des dizaines de graines, et tout recopier ferait un journal plus gros que le resultat.
let __tampon = [];
let __journalSuspendu = false;
function __noterAjout(art, direction, seedLabel, source, neuf){
  if (__journalSuspendu) return;
  const k = art.doi || norm(art.title);
  __tampon.push(neuf ? { a: art, d: direction, l: seedLabel, s: source }
                     : { k: k, d: direction, l: seedLabel, s: source });
}

function addCandidate(art, direction, seedLabel, source){
  if (!art || (!art.title && !art.doi)) return;
  const nt = norm(art.title);
    // TROISIEME RAPPROCHEMENT, SOUS VETO. Le veto retient le candidat des lors qu'il porte un
  // DOI qu'aucune graine homonyme ne porte : deux oeuvres differentes ne se fondent pas.
  // Il ne protege que les paires ou les DEUX cotes ont un DOI, et c'est assumé : sur les 23
  // rapprochements reels il n'est actif que sur 2, et ce sont exactement les 2 qu'il faut
  // retenir (un couple pretirage/publie et deux chapitres homonymes reellement distincts).
  const np = aplat(art.title);
  let dejaPlat = false;
  if (np.length >= PLAT_MIN && corpusPlat.has(np)) {
    const __dois = corpusPlat.get(np);
    const __ad = art.doi ? cleanDoi(art.doi) : '';
    dejaPlat = !(__ad && __dois.size && !__dois.has(__ad));
  }
  if ((art.doi && corpusDoi.has(art.doi)) || (nt && corpusTitle.has(nt)) || dejaPlat){ ecartesVus.add(art.doi || nt); summary.removed_in_corpus_appariements++; return; }
  // MEME UNITE POUR LA REPARTITION PAR BASE. Elle comptait elle aussi des
  // appariements, et elle est publiee dans le meme rapport, une ligne plus bas :
  // corriger un compteur en laissant l'autre remettrait la meme confusion.
  if (summary.by_source[source]) {
